#!/usr/bin/env python3
"""immuno/arcas_hla_typing — auto-generated run.py (archetype=mhc_epitope).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "mhc_epitope"
BRAIN = "immuno"
SKILL = "arcas_hla_typing"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'skill_id': 'arcas_hla_typing', 'n_epitopes': 0, 'epitopes_csv': '', 'diagnostics': {'brain': 'immuno', 'archetype': 'mhc_epitope'}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """arcasHLA HLA typing from RNA-seq BAM(host_env=arcas-hla)。"""
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401
    bam = payload.get("bam_path") or payload.get("input_bam")
    out_dir = payload.get("out_dir") or _tempfile.mkdtemp(prefix="arcas_")
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "tool": "arcasHLA", "out_dir": out_dir}
    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL, "n_epitopes": 0, "epitopes_csv": "",
                "diagnostics": {**diagnostics, "dry": True}}
    if not bam or not _os.path.isfile(bam):
        return {"ok": False, "error": "需要 bam_path", "diagnostics": diagnostics}
    t0 = _time.time()
    # arcasHLA extract → genotype
    r1 = run_tool(["arcasHLA", "extract", "--threads", "8", "-o", out_dir, bam],
                  timeout=int(payload.get("timeout_s", 7200)))
    diagnostics["extract"] = {"wall_sec": r1.get("wall_sec"), "rc": r1.get("returncode")}
    if not r1["ok"]:
        return {"ok": False, "error": r1.get("error", "arcasHLA extract 失败"),
                "stderr": r1.get("stderr", "")[-400:], "diagnostics": diagnostics}
    # 找 extract 出的 fastq
    import glob as _glob
    fq1 = sorted(_glob.glob(_os.path.join(out_dir, "*.extracted.1.fq.gz")))
    fq2 = sorted(_glob.glob(_os.path.join(out_dir, "*.extracted.2.fq.gz")))
    if not fq1:
        return {"ok": False, "error": "arcasHLA extract 未产 fastq", "diagnostics": diagnostics}
    r2 = run_tool(["arcasHLA", "genotype", "--threads", "8", "-o", out_dir, fq1[0]] +
                  ([fq2[0]] if fq2 else []),
                  timeout=int(payload.get("timeout_s", 7200)))
    diagnostics["genotype"] = {"wall_sec": r2.get("wall_sec"), "rc": r2.get("returncode")}
    if not r2["ok"]:
        return {"ok": False, "error": r2.get("error", "arcasHLA genotype 失败"),
                "stderr": r2.get("stderr", "")[-400:], "diagnostics": diagnostics}
    genotype_json = _glob.glob(_os.path.join(out_dir, "*.genotype.json"))
    alleles = {}
    if genotype_json:
        with open(genotype_json[0]) as fh:
            alleles = json.load(fh)
    return {"ok": True, "skill_id": SKILL,
            "n_epitopes": len(alleles),
            "epitopes_csv": genotype_json[0] if genotype_json else "",
            "hla_alleles": alleles,
            "runtime_sec": round(_time.time() - t0, 2), "diagnostics": diagnostics}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
